#!/usr/bin/env node
/**
 * P3 synthetic playable MP4 proof. RUN ONLY on disposable GitHub CI.
 *
 * All source claims, figures, timestamps and coordinates are invented test
 * inputs. This does not invoke any production render entrypoint and does not
 * grant any editorial/media rights, account, upload or publication approval.
 *
 * The actual SVG frames generated by P3-07 are encoded by an already
 * installed ffmpeg binary. No external media, provider or network is used.
 */
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { mkdtemp, readFile, rm, stat, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  makeOfflineGraphicStoryboard,
  buildOfflineVideoCreditsReport,
} from "../packages/shared/dist/index.js";
import {
  normalizeFeedArticles,
  groupExactHeadlineEvents,
  rankOfflineEvents,
  buildOfflineDraft,
  independentlyCheckDraft,
  exportOfflineEditorialReport,
} from "../apps/worker/dist/offline-editorial-pipeline.js";

if (process.env.GITHUB_ACTIONS !== "true" || process.env.CI !== "true") {
  throw new Error("REFUSED: synthetic MP4 proof runs only in disposable GitHub Actions");
}

const PROFILE = Object.freeze({
  id: "synthetic_demo",
  language: "de-DE",
  keywords: ["Synthetische"],
  blockedTerms: ["Sponsored"],
  minIndependentSources: 2,
  maximumArticleAgeHours: 48,
  format: "explainer",
});
const HEADLINE = "Synthetische Meldung zum Testen eigener Nachrichtengrafiken";
const PUBLISHED = "2026-11-08T12:00:00.000Z";
const SOURCES = Object.freeze([
  {
    sourceId: "synthetic_one",
    url: "https://one.example.org/demos/fictional-update",
    headline: HEADLINE,
    publishedAt: PUBLISHED,
    reviewStatus: "candidate",
  },
  {
    sourceId: "synthetic_two",
    url: "https://two.example.org/demos/fictional-update",
    headline: HEADLINE,
    publishedAt: PUBLISHED,
    reviewStatus: "candidate",
  },
]);
const VIDEO_ID = "00000000-0000-4000-8000-000000000901";
const STORY_ID = "00000000-0000-4000-8000-000000000902";
const FPS = 8;
const SECONDS_PER_SCENE = 2;

function command(name, args, timeout = 120000) {
  const result = spawnSync(name, args, {
    shell: false,
    timeout,
    encoding: "utf8",
    maxBuffer: 256 * 1024,
    env: { PATH: process.env.PATH ?? "/usr/bin:/bin" },
  });
  if (result.error || result.status !== 0) {
    throw new Error(
      name +
        " failed (status=" +
        result.status +
        ", cause=" +
        (result.error?.code ?? "none") +
        "): " +
        (result.stderr ?? "").slice(-900),
    );
  }
  return result.stdout;
}

function syntheticStoryboard() {
  const articles = normalizeFeedArticles(SOURCES);
  assert.equal(articles.length, 2);
  const events = groupExactHeadlineEvents(articles);
  assert.equal(events.length, 1);
  const ranked = rankOfflineEvents(events, PROFILE, new Date("2026-11-08T13:00:00.000Z"));
  assert.equal(ranked.length, 1);
  assert.ok(ranked[0].reasons.includes("independent_verification_required"));
  const draft = buildOfflineDraft(ranked[0], PROFILE);
  assert.equal(draft.claims[0].status, "uncertain");
  assert.equal(independentlyCheckDraft(ranked[0], draft).accepted, false);

  const report = exportOfflineEditorialReport(ranked[0], PROFILE, draft);
  assert.equal(report.approvedForPublication, false);
  assert.equal(report.sourceUrls.length, 2);
  assert.ok(report.decisions.includes("unverified_claim"));

  const rights = buildOfflineVideoCreditsReport({ videoId: VIDEO_ID, assets: [] });
  assert.equal(rights.status, "BLOCKED");
  assert.equal(rights.renderAllowed, false);
  assert.equal(rights.uploadAllowed, false);
  assert.equal(rights.creditsVerified, false);
  assert.ok(rights.reasons.includes("no_assets"));

  const sourceUrls = [...report.sourceUrls];
  const storyboard = makeOfflineGraphicStoryboard({
    storyId: STORY_ID,
    publisherApproved: true,
    uploadAllowed: true,
    scenes: [
      {
        kind: "text-card",
        title: draft.headline,
        body:
          "Demo mit erfundenen Daten. Zwei Quellen-IDs sind kein Beweis unabhängiger Recherche. Alle Aussagen bleiben ungeprüft.",
        sourceUrls,
      },
      {
        kind: "table",
        title: "Erfundene Beispielwerte",
        columns: ["Testdatensatz", "Fiktiver Wert"],
        rows: [
          ["Reihe A", "12"],
          ["Reihe B", "24"],
        ],
        sourceUrls,
      },
      {
        kind: "timeline",
        title: "Fiktiver Ablauf",
        entries: [
          { label: "Schritt A", detail: "Synthetischer Startpunkt" },
          { label: "Schritt B", detail: "Synthetischer Endpunkt" },
        ],
        sourceUrls,
      },
      {
        kind: "chart",
        title: "Fiktives Balkendiagramm",
        bars: [
          { label: "Testwert A", value: 12 },
          { label: "Testwert B", value: 24 },
        ],
        sourceUrls,
      },
      {
        kind: "map",
        title: "Schematische Testkarte",
        locations: [
          { label: "Testpunkt A", x: 20, y: 30 },
          { label: "Testpunkt B", x: 75, y: 60 },
        ],
        sourceUrls,
      },
    ],
  });
  assert.equal(storyboard.status, "PREVIEW_ONLY");
  assert.equal(storyboard.frames.length, 5);
  assert.equal(storyboard.sourcesVerified, false);
  assert.equal(storyboard.videoRenderAllowed, false);
  assert.equal(storyboard.uploadAllowed, false);
  return { storyboard, report, rights };
}

async function main() {
  const { storyboard, report, rights } = syntheticStoryboard();
  command("ffmpeg", ["-hide_banner", "-version"], 5000);
  command("ffprobe", ["-hide_banner", "-version"], 5000);

  const dir = await mkdtemp(join(tmpdir(), "vns-p3-synthetic-mp4-"));
  try {
    const paths = [];
    for (const frame of storyboard.frames) {
      assert.ok(frame.svg.startsWith('<svg xmlns="http://www.w3.org/2000/svg"'));
      assert.ok(frame.svg.includes("VORSCHAU – NICHT ZUR VERÖFFENTLICHUNG"));
      assert.doesNotMatch(frame.svg, /<image\b|<script\b|<foreignObject\b|xlink:href\b/);
      const path = join(dir, "scene-" + (frame.index + 1) + ".svg");
      await writeFile(path, frame.svg, { encoding: "utf8", mode: 0o600, flag: "wx" });
      paths.push(path);
    }
    assert.equal(paths.length, 5);

    const inputArgs = paths.flatMap((path) => [
      "-protocol_whitelist",
      "file,pipe",
      "-loop",
      "1",
      "-framerate",
      String(FPS),
      "-t",
      String(SECONDS_PER_SCENE),
      "-i",
      path,
    ]);
    const inputs = paths
      .map((_, i) => "[" + i + ":v]setpts=PTS-STARTPTS,format=yuv420p[v" + i + "]")
      .join(";");
    const sources = paths.map((_, i) => "[v" + i + "]").join("");
    const filters = inputs + ";" + sources + "concat=n=5:v=1:a=0[outv]";
    const mp4 = join(dir, "SYNTHETIC_DO_NOT_PUBLISH.mp4");

    // This is deliberately NOT a production renderer: it has no DB, secrets,
    // public output, upload path or media authorization input.
    command(
      "ffmpeg",
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-nostdin",
        "-y",
        ...inputArgs,
        "-filter_complex",
        filters,
        "-map",
        "[outv]",
        "-an",
        "-r",
        String(FPS),
        "-c:v",
        "libx264",
        "-preset",
        "ultrafast",
        "-crf",
        "32",
        "-pix_fmt",
        "yuv420p",
        "-movflags",
        "+faststart",
        "-metadata",
        "title=SYNTHETIC OFFLINE PREVIEW - NOT FOR PUBLICATION",
        mp4,
      ],
      120000,
    );

    const probe = JSON.parse(
      command("ffprobe", [
        "-v",
        "error",
        "-show_entries",
        "format=duration:stream=codec_name,codec_type,width,height,nb_frames",
        "-of",
        "json",
        mp4,
      ]),
    );
    assert.equal(probe.streams.length, 1);
    assert.equal(probe.streams[0].codec_type, "video");
    assert.equal(probe.streams[0].codec_name, "h264");
    assert.equal(probe.streams[0].width, 1280);
    assert.equal(probe.streams[0].height, 720);
    assert.equal(Number(probe.streams[0].nb_frames), 5 * SECONDS_PER_SCENE * FPS);
    assert.equal(Number(probe.format.duration), 5 * SECONDS_PER_SCENE);
    const size = (await stat(mp4)).size;
    assert.ok(size > 2000 && size < 15 * 1024 * 1024);
    const digest = createHash("sha256").update(await readFile(mp4)).digest("hex");

    assert.equal(report.approvedForPublication, false);
    assert.equal(rights.renderAllowed, false);
    assert.equal(rights.uploadAllowed, false);
    assert.equal(storyboard.videoRenderAllowed, false);
    assert.equal(storyboard.uploadAllowed, false);

    console.log(
      "P3 synthetic MP4 PASS: 5 original SVG scenes, H.264 1280x720, " +
        probe.format.duration +
        " seconds, 0 audio tracks, bytes=" +
        size +
        ", sha256=" +
        digest +
        ".",
    );
    console.log(
      "Editorial approval: DENIED. Media rights: DENIED. Production rendering/upload: NOT ENABLED.",
    );
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

await main();
